import json
import re
import sys
from typing import Any, Dict, Iterable, List, Tuple

# Stop-hook finalization gate for AppWorld runs.
#
# The hook inspects the Claude Code transcript instead of trusting the final
# summary/claim.  It deliberately returns no decision (native behaviour) when
# the Stop input already carries ``stop_hook_active`` true: Claude Code marks a
# Stop hook as active after a previous Stop block, and a Stop hook must let the
# turn end at that point so a blocked run can still terminate.
#
# For action/mutating runs it requires at least one post-action read
# (show_*/search_*/list_* style API call) whose returned text is usable and
# contains the strongly-stated task conditions.  For value/entity runs it
# requires a substantive final answer whose salient values are recomputable
# from observed read results.

MAX_TEXT_CHARS = 200_000
MAX_CODE_CHARS = 50_000

READ_METHOD_RE = re.compile(
    r"\b((?:show|search|list|get|find|query|lookup|view)_[A-Za-z0-9_]+)\s*\("
)
MUTATE_METHOD_RE = re.compile(
    r"\b((?:add|create|update|delete|remove|send|pay|transfer|book|order|post|"
    r"schedule|cancel|modify|write|upload|subscribe|unsubscribe|register|buy|"
    r"sell|complete|submit|set|change|insert)_[A-Za-z0-9_]+)\s*\("
)

EMAIL_RE = re.compile(r"\b[\w.+-]+@[\w-]+\.[\w.-]+\b")
PHONE_RE = re.compile(
    r"\b(?:\+\d{1,3}[- ]?)?\(?\d{3}\)?[- .]?\d{3}[- .]?\d{4}\b"
)
MONEY_RE = re.compile(r"(?:\$\s?|\bUSD\s?|\bEUR\s?|\bGBP\s?)\d[\d,]*\.?\d*\b", re.I)
DATE_RE = re.compile(
    r"\b(?:\d{1,2}[/-]\d{1,2}[/-]\d{2,4}|\d{4}-\d{2}-\d{2}|"
    r"(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s+\d{1,2}(?:,\s+\d{4})?)",
    re.I,
)
TIME_RE = re.compile(r"\b(?:\d{1,2}:\d{2}\s?(?:am|pm)?|\d{1,2}\s?(?:am|pm))\b", re.I)
NUMBER_RE = re.compile(r"\b\d[\d,]*\.?\d*\b")
QUOTED_RE = re.compile(r"[\"']([^\"']{1,80})[\"']")
KEY_VALUE_RE = re.compile(
    r"\b(?:status|state|balance|amount|name|email|phone|address|price|quantity|"
    r"limit|color|size|type|category|date|time|title|location)\s*"
    r"(?:is|are|be|must be|should be|to|=|:)\s+([^,.;]{1,40})",
    re.I,
)
TO_VALUE_RE = re.compile(
    r"\b(?:set|change|update|make|mark|turn|convert|rename|move|transfer)\s+"
    r"(?:the\s+)?([^,.;]{0,50}?)\s+to\s+([^,.;]{1,60})",
    re.I,
)

MUTATE_TASK_RE = re.compile(
    r"\b(?:add|create|update|change|delete|remove|send|pay|transfer|book|order|"
    r"post|schedule|cancel|modify|write|upload|subscribe|unsubscribe|register|"
    r"buy|sell|complete|submit|set)\s",
    re.I,
)
VALUE_QUESTION_RE = re.compile(
    r"^\s*(?:what|when|where|who|which|how many|how much|list|show|find|search|"
    r"get|display|tell me|report|is there|are there)\b",
    re.I,
)
CONJUNCTIVE_MUTATE_RE = re.compile(
    r"\band\s+(?:then\s+)?(?:add|create|update|change|delete|remove|send|pay|"
    r"transfer|book|order|post|schedule|cancel|modify|write|upload|subscribe|"
    r"unsubscribe|register|buy|sell|complete|submit|set)\b",
    re.I,
)

STOPWORDS = {
    "the", "and", "for", "are", "but", "not", "you", "all", "can", "had",
    "her", "was", "one", "our", "out", "has", "his", "they", "have", "this",
    "that", "with", "from", "will", "would", "there", "their", "what",
    "about", "which", "when", "where", "who", "whom", "your", "yours", "theirs",
    "these", "those", "been", "being", "does", "did", "doing", "into", "onto",
    "then", "than", "them", "some", "such", "each", "very", "just", "also",
    "after", "before", "over", "under", "again", "further", "once", "here",
    "why", "how", "should", "could", "might", "must", "shall", "may",
    "need", "task", "complete", "completed", "done", "answer", "question",
    "please", "api", "appworld", "world", "result", "results", "record",
    "records", "value", "values", "output", "using", "use", "via", "per",
    "following", "follows", "given", "according", "based", "observed", "show",
    "list", "search", "find", "get", "look", "view", "query", "return",
    "returned", "returns", "contains", "containing", "include", "including",
    "than", "like", "want", "tell", "give", "provide", "report", "state",
    "say", "said", "shows", "showed", "found", "see", "check", "verify",
    "make", "sure",
}

COMPLETION_PHRASES = (
    "task complete",
    "task completed",
    "tasks complete",
    "tasks completed",
    "the task is complete",
    "the task is completed",
    "task is complete",
    "task is now complete",
    "task has been completed",
    "task has now been completed",
    "completed the task",
    "i have completed the task",
    "all done",
    "all tasks complete",
    "all tasks completed",
    "done",
    "finished",
    "complete",
    "completed",
)

EMPTY_OUTPUTS = {"[]", "{}", "null", "none", "0", "no results", "no result",
                 "no records", "no events", "no tasks", "no emails",
                 "no messages", "no contacts", "no orders", "no transactions",
                 "no appointments", "no notifications"}


def normalize(value: Any) -> str:
    """Return a stable, lower-cased, single-spaced string for comparison."""
    text = str(value if value is not None else "")
    text = text.lower()
    text = text.replace("\u00a0", " ")
    text = re.sub(r"\s+", " ", text)
    return text.strip()


def _unique(values: Iterable[str]) -> List[str]:
    seen: List[str] = []
    for value in values:
        value = normalize(value)
        if value and value not in seen:
            seen.append(value)
    return seen


def extract_text_from_content(content: Any) -> str:
    """Flatten a transcript content field (str, dict, or list) to plain text."""
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts: List[str] = []
        for item in content:
            if isinstance(item, str):
                parts.append(item)
            elif isinstance(item, dict):
                text = item.get("text") or item.get("content")
                if isinstance(text, str):
                    parts.append(text)
                elif isinstance(text, list):
                    parts.append(extract_text_from_content(text))
                else:
                    parts.append(str(text))
            else:
                parts.append(str(item))
        return "\n".join(part for part in parts if part)
    if isinstance(content, dict):
        text = content.get("text") or content.get("content")
        if isinstance(text, str):
            return text
        if isinstance(text, list):
            return extract_text_from_content(text)
        return str(text)
    return str(content)


def extract_code_from_input(tool_input: Any) -> str:
    """Return the executable source text that an AppWorld tool call used."""
    if tool_input is None:
        return ""
    if isinstance(tool_input, str):
        return tool_input
    if isinstance(tool_input, dict):
        for key in ("code", "command", "script", "source"):
            value = tool_input.get(key)
            if isinstance(value, str) and value:
                return value
        parts: List[str] = []
        for value in tool_input.values():
            if isinstance(value, str):
                parts.append(value)
            elif isinstance(value, dict):
                parts.append(extract_code_from_input(value))
        return "\n".join(part for part in parts if part)
    return ""


def entry_role(entry: Dict[str, Any]) -> str:
    role = entry.get("type", "")
    if role in ("assistant", "user", "system"):
        return role
    message = entry_message(entry)
    message_role = message.get("role", "")
    if message_role in ("assistant", "user", "system"):
        return message_role
    return ""


def entry_message(entry: Dict[str, Any]) -> Dict[str, Any]:
    message = entry.get("message")
    if isinstance(message, str):
        try:
            parsed = json.loads(message)
            if isinstance(parsed, dict):
                return parsed
        except json.JSONDecodeError:
            pass
        return {}
    if isinstance(message, dict):
        return message
    return {}


def entry_content(entry: Dict[str, Any]) -> Any:
    message = entry_message(entry)
    if "content" in message:
        return message.get("content")
    if "content" in entry:
        return entry.get("content")
    return None


def iter_content_blocks(entry: Dict[str, Any]) -> Iterable[Any]:
    content = entry_content(entry)
    if isinstance(content, list):
        for block in content:
            if isinstance(block, dict):
                yield block
            elif isinstance(block, str):
                yield {"type": "text", "text": block}
    elif isinstance(content, dict):
        yield content
    elif isinstance(content, str):
        yield {"type": "text", "text": content}


def collect_transcript_evidence(
    transcript_path: str,
) -> Tuple[str, str, List[Dict[str, Any]]]:
    """Return task text, final assistant text, and chronological tool calls."""
    task_parts: List[str] = []
    final_assistant_text = ""
    tool_calls: List[Dict[str, Any]] = []
    ordered_results: List[Dict[str, str]] = []

    try:
        handle = open(transcript_path, "r", encoding="utf-8", errors="replace")
    except OSError:
        return "", "", []

    try:
        with handle:
            for line in handle:
                line = line.strip()
                if not line:
                    continue
                try:
                    entry = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if not isinstance(entry, dict):
                    continue

                role = entry_role(entry)
                if role == "assistant":
                    for block in iter_content_blocks(entry):
                        block_type = block.get("type")
                        if block_type == "text":
                            text = extract_text_from_content(block.get("text"))
                            if text and text.strip():
                                final_assistant_text = text[:MAX_TEXT_CHARS]
                        elif block_type == "tool_use":
                            tool_input = block.get(
                                "input", block.get("tool_input", {})
                            )
                            tool_calls.append({
                                "index": len(tool_calls),
                                "id": block.get("id") or block.get("tool_use_id"),
                                "name": block.get("name") or block.get("tool_name") or "",
                                "code": extract_code_from_input(tool_input)[:MAX_CODE_CHARS],
                                "output": "",
                                "has_read": False,
                                "has_mutate": False,
                                "read_after_mutate": False,
                            })
                elif role == "user":
                    for block in iter_content_blocks(entry):
                        block_type = block.get("type")
                        if block_type == "text":
                            text = extract_text_from_content(block.get("text"))
                            if text and text.strip():
                                task_parts.append(text[:MAX_TEXT_CHARS])
                        elif block_type == "tool_result":
                            tool_use_id = block.get("tool_use_id")
                            text = extract_text_from_content(
                                block.get("content")
                            )[:MAX_TEXT_CHARS]
                            ordered_results.append({"id": tool_use_id, "text": text})
    except (OSError, ValueError):
        return "", "", []

    # Attach results by id where possible, then fall back to transcript order
    # for any remaining calls (some transcript formats omit or rename ids).
    results_by_id: Dict[str, List[int]] = {}
    for index, result in enumerate(ordered_results):
        result_id = result.get("id")
        if result_id:
            results_by_id.setdefault(result_id, []).append(index)

    used_result_indices: set = set()
    unmatched_calls: List[Dict[str, Any]] = []
    for call in tool_calls:
        call_id = call.get("id")
        if call_id and results_by_id.get(call_id):
            result_index = results_by_id[call_id].pop(0)
            call["output"] = ordered_results[result_index].get("text", "")
            used_result_indices.add(result_index)
        else:
            unmatched_calls.append(call)

    unmatched_results = [
        result for index, result in enumerate(ordered_results)
        if index not in used_result_indices
    ]
    for call, result in zip(unmatched_calls, unmatched_results):
        call["output"] = result.get("text", "")

    for call in tool_calls:
        annotate_call(call)

    task_text = "\n".join(part for part in task_parts if part.strip())
    return task_text, final_assistant_text, tool_calls


def annotate_call(call: Dict[str, Any]) -> None:
    code = call.get("code", "") or ""
    read_positions = [match.start() for match in READ_METHOD_RE.finditer(code)]
    mutate_positions = [match.start() for match in MUTATE_METHOD_RE.finditer(code)]
    has_read = bool(read_positions)
    has_mutate = bool(mutate_positions)
    call["has_read"] = has_read
    call["has_mutate"] = has_mutate
    if has_read and has_mutate:
        call["read_after_mutate"] = max(read_positions) > max(mutate_positions)
    else:
        call["read_after_mutate"] = has_read


def output_is_usable(text: str) -> bool:
    """Return True for non-empty, non-error tool output."""
    if not text or not text.strip():
        return False
    stripped = text.strip()
    lowered = stripped.lower()
    if lowered in {"null", "none", "{}", "[]"}:
        return False
    if '"isError": true' in lowered or '"isError":true' in lowered:
        return False
    if re.search(r"(?m)^(Traceback \(most recent call last\)|Error:|Exception:)", stripped):
        return False
    return True


def output_is_observation(text: str) -> bool:
    """Return True for output that is either usable or a valid empty result."""
    if output_is_usable(text):
        return True
    normalized = normalize(text)
    return normalized in {"[]", "{}", "null", "none", "0"}


def extract_typed_values(text: str) -> List[str]:
    """Extract typed answer values (email, phone, money, date, time, quoted)."""
    values: List[str] = []
    for pattern in (EMAIL_RE, PHONE_RE, MONEY_RE, DATE_RE, TIME_RE):
        for match in pattern.finditer(text):
            values.append(normalize(match.group(0)))
    for match in QUOTED_RE.finditer(text):
        quoted = normalize(match.group(1))
        if 1 <= len(quoted) <= 80:
            values.append(quoted)
    for match in NUMBER_RE.finditer(text):
        number = normalize(match.group(0))
        # Include meaningful numeric answers but avoid counting every single
        # digit or year-like value as a standalone answer.
        if len(number) >= 2 or number == "0":
            values.append(number)
    return _unique(values)


def looks_typed(value: str) -> bool:
    return bool(
        EMAIL_RE.search(value)
        or PHONE_RE.search(value)
        or MONEY_RE.search(value)
        or DATE_RE.search(value)
        or TIME_RE.search(value)
        or re.search(r"\d", value)
    )


def extract_expected_conditions(task_text: str) -> List[str]:
    """Extract strongly-stated task conditions that a final state should show.

    This is deliberately conservative.  The primary gate is the existence of a
    post-action read; these snippets add a generic, non-answer-specific check
    for stable literals (quotes, emails, phones) and explicit ``to`` /
    ``key is ...`` targets.
    """
    values: List[str] = []

    for match in QUOTED_RE.finditer(task_text):
        quoted = normalize(match.group(1))
        if 1 <= len(quoted) <= 60:
            values.append(quoted)

    for pattern in (EMAIL_RE, PHONE_RE):
        for match in pattern.finditer(task_text):
            values.append(normalize(match.group(0)))

    for match in TO_VALUE_RE.finditer(task_text):
        raw_target = match.group(2).strip()
        target = raw_target.strip("\"'")
        if not target or len(target) > 60:
            continue
        if len(target.split()) == 1 or looks_typed(target) or raw_target != target:
            values.append(normalize(target))

    for match in KEY_VALUE_RE.finditer(task_text):
        raw_value = match.group(1).strip()
        value = raw_value.strip("\"'")
        if not value or len(value) > 40:
            continue
        if len(value.split()) == 1 or looks_typed(value) or raw_value != value:
            values.append(normalize(value))

    return _unique(values)


def condition_matches(value: str, text: str) -> bool:
    """Return True when a condition value is reflected in observed state text."""
    if not value:
        return False
    if value in text:
        return True

    # Allow a currency-formatted condition to match a plain numeric state
    # (e.g. task "$50" vs observed "amount: 50").
    money = re.fullmatch(r"(?:\$|usd|eur|gbp)?\s*(\d[\d,]*\.?\d*)", value)
    if money:
        number = money.group(1)
        if re.search(r"(?<!\d)" + re.escape(number) + r"(?!\d)", text):
            return True

    # Allow minor date separator differences.
    date_like = re.fullmatch(r"\d{1,2}[/-]\d{1,2}[/-]\d{2,4}", value)
    if date_like:
        parts = re.split(r"[/-]", value)
        if len(parts) == 3:
            alt = "-".join(parts)
            if alt in text:
                return True
    return False


def task_is_mutating(task_text: str, tool_calls: List[Dict[str, Any]]) -> bool:
    if any(call.get("has_mutate") for call in tool_calls):
        return True
    if not task_text:
        return False

    value_question = VALUE_QUESTION_RE.match(task_text)
    if MUTATE_TASK_RE.search(task_text) and not value_question:
        return True

    # A query that continues with "and <mutate>" is still an action task
    # (e.g. "Find and update ..."), not a pure value/entity request.
    if value_question:
        rest = task_text[value_question.end():]
        if CONJUNCTIVE_MUTATE_RE.search(rest):
            return True
    return False


def substantive_answer(text: str) -> bool:
    answer = normalize(text)
    if not answer:
        return False
    if answer in {"done", "complete", "completed", "finished", "all done"}:
        return False
    # Remove a leading "task complete"-style claim and see whether an actual
    # answer remains.
    for phrase in sorted(COMPLETION_PHRASES, key=len, reverse=True):
        if answer.startswith(phrase):
            rest = answer[len(phrase):].strip(" .!;:,-")
            return len(rest) >= 1
    return True


def final_answer_from(
    transcript_answer: str, event: Dict[str, Any]
) -> str:
    """Pick the most likely final answer from the Stop event or transcript."""
    event_answer = str(event.get("last_assistant_message") or "").strip()
    if event_answer and substantive_answer(event_answer):
        return event_answer

    transcript_answer = (transcript_answer or "").strip()
    if transcript_answer and substantive_answer(transcript_answer):
        return transcript_answer

    return event_answer or transcript_answer


def is_empty_answer(answer: str) -> bool:
    text = normalize(answer)
    if text in EMPTY_OUTPUTS:
        return True
    return bool(
        re.match(
            r"^(?:there are|there is|there were|there was)?\s*no\b.*",
            text,
        )
        and not any(ch.isdigit() for ch in text)
    )


def is_empty_output(output: str) -> bool:
    text = normalize(output)
    if text in EMPTY_OUTPUTS:
        return True
    if text.startswith("no ") and len(text) < 80:
        return True
    return False


def answer_grounded(answer: str, read_outputs: List[str]) -> bool:
    if not substantive_answer(answer):
        return False
    if not read_outputs:
        return False
    combined = normalize("\n".join(read_outputs))
    answer_normalized = normalize(answer)

    if is_empty_answer(answer) and any(is_empty_output(output) for output in read_outputs):
        return True

    typed_snippets = extract_typed_values(answer)
    if typed_snippets:
        return any(snippet in combined for snippet in typed_snippets)

    # Fall back to salient words in prose answers.
    fallback = [
        word for word in re.findall(r"[A-Za-z0-9]+", answer_normalized)
        if word not in STOPWORDS and len(word) >= 3
    ]
    if not fallback:
        return False
    return any(word in combined for word in fallback)


def mutating_check(
    task_text: str, tool_calls: List[Dict[str, Any]]
) -> Tuple[bool, str]:
    mutate_calls = [call for call in tool_calls if call.get("has_mutate")]
    if not mutate_calls:
        return False, (
            "Do not finish yet. No mutating AppWorld API call was observed in "
            "the transcript. Perform the required action, then re-read the "
            "affected state with the appropriate show_/search_/list API and "
            "verify the returned state against every task condition before "
            "stopping."
        )

    last_mutate_index = max(call["index"] for call in mutate_calls)
    post_reads: List[Dict[str, Any]] = []
    for call in tool_calls:
        if not call.get("has_read"):
            continue
        if call["index"] > last_mutate_index:
            post_reads.append(call)
        elif call["index"] == last_mutate_index and call.get("read_after_mutate"):
            post_reads.append(call)

    usable_reads = [call for call in post_reads if output_is_usable(call.get("output", ""))]
    if not post_reads:
        return False, (
            "Do not finish yet. A mutating action is present but no later "
            "show_/search_/list read of the affected state was found. Re-read "
            "the relevant state with the appropriate read API, verify every "
            "task condition against the returned values, and report the "
            "observed state before stopping."
        )
    if not usable_reads:
        return False, (
            "Do not finish yet. The post-action show_/search_/list read "
            "returned no usable state (empty or error). Re-run the relevant "
            "read API after the action, verify every task condition, and "
            "report the observed state before stopping."
        )

    expected = extract_expected_conditions(task_text)
    if not expected:
        return True, ""

    combined = normalize("\n".join(call.get("output", "") for call in usable_reads))
    missing = [value for value in expected if not condition_matches(value, combined)]
    if missing:
        preview = ", ".join(missing[:5])
        if len(missing) > 5:
            preview += ", ..."
        return False, (
            "Do not finish yet. The observed post-action state does not yet "
            f"show expected condition(s): {preview}. Re-read the relevant "
            "state with the appropriate show_/search_/list API, verify every "
            "task condition, and report the observed state before stopping."
        )
    return True, ""


def value_check(
    task_text: str,
    transcript_answer: str,
    event: Dict[str, Any],
    tool_calls: List[Dict[str, Any]],
) -> Tuple[bool, str]:
    answer = final_answer_from(transcript_answer, event)
    if not substantive_answer(answer):
        return False, (
            "Do not finish yet. The final message does not contain an answer "
            "that can be checked. Re-run the relevant show_/search_/list API, "
            "compute the requested value or entity from the returned records, "
            "and state that answer explicitly before stopping."
        )

    read_calls = [call for call in tool_calls if call.get("has_read")]
    if not read_calls:
        return False, (
            "Do not finish yet. No show_/search_/list observation was found "
            "to support the answer. Re-run the relevant read API and derive "
            "the answer from the returned records before stopping."
        )

    observations = [
        call.get("output", "") for call in read_calls
        if output_is_observation(call.get("output", ""))
    ]
    if not observations:
        return False, (
            "Do not finish yet. The show_/search_/list calls returned no "
            "usable records. Re-run the relevant read API and derive the "
            "answer from the returned records before stopping."
        )

    if not answer_grounded(answer, observations):
        return False, (
            "Do not finish yet. The submitted answer cannot be recomputed from "
            "the observed show_/search_/list results. Re-run the relevant read "
            "API, compute the answer from those records, and report the answer "
            "together with the supporting observed values before stopping."
        )
    return True, ""


def decide(event: Dict[str, Any]) -> Dict[str, Any]:
    if event.get("hook_event_name") != "Stop":
        return {}

    # Claude Code marks a Stop hook active after a previous Stop block.  The
    # hook must allow the turn to end in that state so blocked runs terminate.
    if event.get("stop_hook_active"):
        return {}

    # A non-empty background task list means the session is pausing for work
    # that will wake it again; do not block that native lifecycle.
    background_tasks = event.get("background_tasks")
    if isinstance(background_tasks, list) and background_tasks:
        return {}

    transcript_path = event.get("transcript_path")
    if not transcript_path:
        return {}

    task_text, transcript_answer, tool_calls = collect_transcript_evidence(
        transcript_path
    )
    if not tool_calls and not task_text:
        return {}

    if task_is_mutating(task_text, tool_calls):
        allowed, reason = mutating_check(task_text, tool_calls)
    else:
        allowed, reason = value_check(
            task_text, transcript_answer, event, tool_calls
        )

    if allowed:
        return {}
    return {"decision": "block", "reason": reason}


def main() -> None:
    raw = ""
    try:
        raw = sys.stdin.read()
    except (OSError, ValueError):
        raw = ""

    event: Dict[str, Any] = {}
    if raw.strip():
        try:
            parsed = json.loads(raw)
            if isinstance(parsed, dict):
                event = parsed
        except json.JSONDecodeError:
            event = {}

    try:
        decision = decide(event)
    except Exception:
        # A completion hook must never crash the native stop path; fall back
        # to the original permissive behaviour if transcript inspection fails.
        decision = {}

    print(json.dumps(decision, ensure_ascii=False))


if __name__ == "__main__":
    main()

